mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.member member,
  ttokssaemdb.branch branch
WHERE
  member.branchid = branch.branchid

    AND member.branchid = #{session_branchid}


    AND member.type = #{type}


    AND member.classyn = #{classyn}


    AND (
      member.membername LIKE #{likeQuery}
      OR
      member.contact LIKE #{likeQuery}
    )


    AND member.memberno = ${query}

SELECT R1.* FROM( SELECT branch.branchid, branch.branchname, member.memberno, member.memberid, member.type, (SELECT count(*) FROM ttokssaemdb.parents WHERE parentid = member.memberid) child, member.membername, member.schoolcode, member.schoolname, member.grade, member.gender, member.contact, member.email, member.os, member.pushtoken, member.marketing, member.push, member.classyn, member.accessyn, DATE_FORMAT(member.classexpiredate, '%Y-%m-%d') classexpiredate, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid),0) total_blackmark, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid AND ( regdate > LAST_DAY(NOW() - interval 1 month) AND regdate <= LAST_DAY(NOW()) )), 0) month_blackmark, DATE_FORMAT(member.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.member member, ttokssaemdb.branch branch
AND member.branchid = branch.branchid
AND member.branchid = #{session_branchid}
AND member.type = #{type}
AND member.classyn = #{classyn}
AND ( member.membername LIKE #{likeQuery} OR member.contact LIKE #{likeQuery} )
AND member.memberno = ${query}
member.regdate member.memberid branch.branchname member.membername member.type member.schoolcode member.schoolname member.grade member.contact member.email member.classyn member.accessyn member.os member.marketing member.push member.classexpiredate month_blackmark member.regdate DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}

SELECT branch.branchid, branch.branchname, member.memberno, member.memberid, member.type, member.membername, member.schoolcode, member.schoolname, member.grade, member.gender, member.contact, member.email, member.os, member.pushtoken, member.marketing, member.push, member.classyn, member.accessyn, DATE_FORMAT(member.classexpiredate, '%Y-%m-%d') classexpiredate, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid),0) total_blackmark, IFNULL((SELECT SUM(point) FROM blackmark WHERE memberid = member.memberid AND ( regdate > LAST_DAY(NOW() - interval 1 month) AND regdate <= LAST_DAY(NOW()) )), 0) month_blackmark, DATE_FORMAT(member.regdate, '%Y-%m-%d %H:%i:%s') regdate FROM ttokssaemdb.member member, ttokssaemdb.branch branch
AND member.branchid = branch.branchid
AND member.memberid = #{memberid}

SELECT parentid as memberid FROM ttokssaemdb.parents WHERE memberid IN ( SELECT member.memberid FROM ttokssaemdb.member member
AND member.branchid = #{branchid} AND member.type = 'S' AND member.classyn ='Y'
)

mapper.delete:
DELETE FROM ttokssaemdb.member

  AND branchid = #{branchid}
  AND memberid = #{memberid}

mapper.select:
SELECT member.memberno, member.memberid, member.type, member.membername, member.schoolname, member.grade, member.gender, member.contact FROM ttokssaemdb.member member
AND member.branchid = #{session_branchid}
AND member.type = #{type}
AND member.classyn = #{classyn}
member.membername member.schoolname ASC ASC DESC

SELECT * FROM ( SELECT member.memberno, member.memberid, member.type, member.membername, member.schoolname, member.grade, member.gender, member.contact, -- 존재하면 1, 없으면 0 CASE WHEN rp.exist_flag = 1 THEN 1 ELSE 0 END AS cnt FROM ttokssaemdb.member AS member LEFT JOIN ( -- 존재 여부만 만들기: DISTINCT → exist_flag=1 SELECT DISTINCT memberid, 1 AS exist_flag FROM ttokssaemdb.runtimeplan WHERE dayofweek = 1 AND status <> 3 ) AS rp ON rp.memberid = member.memberid
AND member.branchid = #{session_branchid}
AND member.type = #{type}
AND member.classyn = #{classyn}
) T ORDER BY T.cnt DESC, T.membername ASC
